--
-- Name: fn_apply_disposal_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_apply_disposal_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_rules public.waste_rules%ROWTYPE;
  v_used_before numeric(14,3);
  v_used_after  numeric(14,3);
  v_capacity    numeric(14,3);
  v_load_m3     numeric(14,3);
BEGIN
  -- Load rules for municipality; if missing, use defaults by building a record
  SELECT *
  INTO v_rules
  FROM public.waste_rules
  WHERE municipality_id = NEW.municipality_id;

  IF NOT FOUND THEN
    -- default ratios match your screenshot-like split: 30/24/28/11/7 = 100%
    v_rules.bio_ratio := 0.30;
    v_rules.plastic_ratio := 0.24;
    v_rules.cardboard_ratio := 0.28;
    v_rules.metal_ratio := 0.11;
    v_rules.other_ratio := 0.07;

    -- default densities (kg/m3). Tune these later.
    v_rules.bio_kg_per_m3 := 600;
    v_rules.plastic_kg_per_m3 := 80;
    v_rules.cardboard_kg_per_m3 := 120;
    v_rules.metal_kg_per_m3 := 900;
    v_rules.other_kg_per_m3 := 200;
  END IF;

  -- Split weights from total
  NEW.bio_kg       := round(NEW.total_weight_kg * v_rules.bio_ratio, 3);
  NEW.plastic_kg   := round(NEW.total_weight_kg * v_rules.plastic_ratio, 3);
  NEW.cardboard_kg := round(NEW.total_weight_kg * v_rules.cardboard_ratio, 3);
  NEW.metal_kg     := round(NEW.total_weight_kg * v_rules.metal_ratio, 3);
  NEW.other_kg     := round(NEW.total_weight_kg * v_rules.other_ratio, 3);

  -- Compute volume from densities: volume = kg / (kg per m3)
  v_load_m3 :=
    (NEW.bio_kg       / v_rules.bio_kg_per_m3)
  + (NEW.plastic_kg   / v_rules.plastic_kg_per_m3)
  + (NEW.cardboard_kg / v_rules.cardboard_kg_per_m3)
  + (NEW.metal_kg     / v_rules.metal_kg_per_m3)
  + (NEW.other_kg     / v_rules.other_kg_per_m3);

  NEW.load_volume_m3 := round(v_load_m3, 3);

  -- Lock the landfill row so parallel inserts don’t race
  SELECT used_m3, capacity_m3
  INTO v_used_before, v_capacity
  FROM public.landfill_sites
  WHERE id = NEW.landfill_site_id
  FOR UPDATE;

  v_used_after := v_used_before + NEW.load_volume_m3;

  IF v_used_after > v_capacity THEN
    RAISE EXCEPTION 'Landfill capacity exceeded. used_after=%, capacity=%', v_used_after, v_capacity;
  END IF;

  UPDATE public.landfill_sites
  SET used_m3 = v_used_after,
      updated_at = now()
  WHERE id = NEW.landfill_site_id;

  NEW.landfill_used_before_m3 := round(v_used_before, 3);
  NEW.landfill_used_after_m3  := round(v_used_after, 3);

  RETURN NEW;
END;
$$;


--
-- Name: rollup_emissions(timestamp with time zone, timestamp with time zone, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rollup_emissions(p_from timestamp with time zone, p_to timestamp with time zone, p_granularity text, p_municipality_id bigint DEFAULT NULL::bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF p_granularity NOT IN ('minute','hour','day','month') THEN
    RAISE EXCEPTION 'Unsupported granularity: %', p_granularity;
  END IF;

    municipality_id, bucket, granularity,
    co2_kg, co_kg,
    co2e_kg, carbon_tax_eur, warming_c
  )
  SELECT
    t.municipality_id,
    date_trunc(p_granularity, tel."timestamp") AS bucket,
    p_granularity AS granularity,

    COALESCE(SUM(tel.co2_kg), 0) AS co2_kg,
    COALESCE(SUM(tel.co_kg), 0)  AS co_kg,

    -- Carbon Footprint CO2e (kg): CO2 + CO*3.0
    (COALESCE(SUM(tel.co2_kg), 0) + (COALESCE(SUM(tel.co_kg), 0) * 3.0)) AS co2e_kg,

    -- Carbon tax (€): (kg -> tonne) * €92
    ((COALESCE(SUM(tel.co2_kg), 0) + (COALESCE(SUM(tel.co_kg), 0) * 3.0)) / 1000.0) * 92.0 AS carbon_tax_eur,

    -- Warming (°C): (CO2 + CO*1.9) * 4.5e-16
    ((COALESCE(SUM(tel.co2_kg), 0) + (COALESCE(SUM(tel.co_kg), 0) * 1.9)) * 4.5e-16) AS warming_c

  FROM public.telemetry tel
  JOIN public.trucks t ON t.id = tel.truck_id
  WHERE tel."timestamp" >= p_from
    AND tel."timestamp" <  p_to
    AND t.vehicle_role IN ('waste_truck','support_car')
    AND (p_municipality_id IS NULL OR t.municipality_id = p_municipality_id)
  GROUP BY
    t.municipality_id,
    date_trunc(p_granularity, tel."timestamp")

  ON CONFLICT (municipality_id, bucket, granularity)
  DO UPDATE SET
    co2_kg         = EXCLUDED.co2_kg,
    co_kg          = EXCLUDED.co_kg,
    co2e_kg        = EXCLUDED.co2e_kg,
    carbon_tax_eur = EXCLUDED.carbon_tax_eur,
    warming_c      = EXCLUDED.warming_c,
    created_at     = now();

END;
$$;


--
-- Name: set_telemetry_fuel_type(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_telemetry_fuel_type() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.fuel_type IS NULL THEN
    SELECT t.fuel_type INTO NEW.fuel_type
    FROM trucks t
    WHERE t.id = NEW.truck_id;
  END IF;

  RETURN NEW;
END;
$$;


