--
-- Name: v_disposal_ui_rows; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_disposal_ui_rows AS
 SELECT de.id,
    (de.occurred_at)::date AS date,
    t.truck_code AS truck_id,
    ((de.total_weight_kg / 1000.0))::numeric(14,2) AS total_waste_t,
    ((de.bio_kg / 1000.0))::numeric(14,2) AS bio_t,
    ((de.plastic_kg / 1000.0))::numeric(14,2) AS plastic_t,
    ((de.cardboard_kg / 1000.0))::numeric(14,2) AS cardboard_t,
    ((de.metal_kg / 1000.0))::numeric(14,2) AS metal_t,
    ((de.other_kg / 1000.0))::numeric(14,2) AS other_t,
    de.load_volume_m3 AS landfill_used_m3,
    de.landfill_used_after_m3 AS landfill_total_used_m3,
    de.municipality_id,
    de.landfill_site_id
   FROM (public.disposal_events de
     JOIN public.trucks t ON ((t.id = de.truck_id)));


