--

CREATE TABLE public.waste_load_events (
    id bigint NOT NULL,
    trip_id bigint NOT NULL,
    truck_id integer NOT NULL,
    occurred_at timestamp with time zone NOT NULL,
    waste_type character varying(30) NOT NULL,
    weight_kg numeric(12,3) NOT NULL,
    loading_minutes numeric(10,2),
    co2_kg_loading numeric(12,6),
    co_kg_loading numeric(12,6),
    CONSTRAINT waste_load_events_waste_type_check CHECK (((waste_type)::text = ANY ((ARRAY['mixed'::character varying, 'wet'::character varying, 'dry'::character varying, 'recyclable'::character varying, 'hazardous'::character varying])::text[])))
);


