--
-- Name: waste_rules; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.waste_rules (
    municipality_id bigint NOT NULL,
    bio_ratio numeric(6,5) DEFAULT 0.30000 NOT NULL,
    plastic_ratio numeric(6,5) DEFAULT 0.24000 NOT NULL,
    cardboard_ratio numeric(6,5) DEFAULT 0.28000 NOT NULL,
    metal_ratio numeric(6,5) DEFAULT 0.11000 NOT NULL,
    other_ratio numeric(6,5) DEFAULT 0.07000 NOT NULL,
    bio_kg_per_m3 numeric(10,3) DEFAULT 600 NOT NULL,
    plastic_kg_per_m3 numeric(10,3) DEFAULT 80 NOT NULL,
    cardboard_kg_per_m3 numeric(10,3) DEFAULT 120 NOT NULL,
    metal_kg_per_m3 numeric(10,3) DEFAULT 900 NOT NULL,
    other_kg_per_m3 numeric(10,3) DEFAULT 200 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_ratios_sum CHECK ((abs((((((bio_ratio + plastic_ratio) + cardboard_ratio) + metal_ratio) + other_ratio) - 1.0)) < 0.00001))
);


